function jsonTypeToJoi(node) {
    if (node.$ref) {
        const name = String(node.$ref).split("/").pop();
        return name ? name + "Schema" : "J.any()";
    }
    if (node.enum)
        return `J.valid(${node.enum.map((e) => JSON.stringify(e)).join(", ")})`;
    switch (node.type) {
        case "string":
            if (node.format === "email")
                return "J.string().email()";
            if (node.format === "uuid")
                return "J.string().uuid()";
            if (node.format === "date")
                return "J.string().isoDate()";
            if (node.format === "date-time")
                return "J.string().isoDate()";
            if (node.format === "uri")
                return "J.string().uri()";
            return "J.string()";
        case "integer": return "J.number().integer()";
        case "number": return "J.number()";
        case "boolean": return "J.boolean()";
        case "array": {
            const items = jsonTypeToJoi(node.items || {});
            let j = `J.array().items(${items})`;
            if (node.minItems !== undefined)
                j += `.min(${node.minItems})`;
            if (node.maxItems !== undefined)
                j += `.max(${node.maxItems})`;
            if (node.uniqueItems)
                j += `.unique()`;
            return j;
        }
        case "object":
            return "J.object()";
        default:
            return "J.any()";
    }
}
export function generateJoiModule(schema) {
    const defs = schema.definitions || {};
    const blocks = [];
    for (const [name, def] of Object.entries(defs)) {
        const props = def.properties || {};
        const req = new Set(def.required || []);
        const entries = Object.entries(props).map(([k, v]) => {
            let j = jsonTypeToJoi(v);
            if (req.has(k))
                j += `.required()`;
            return `  ${JSON.stringify(k)}: ${j}`;
        });
        blocks.push(`export const ${name}Schema = J.object({\n${entries.join(",\n")}\n})${def.additionalProperties === false ? ".unknown(false)" : ""};`);
    }
    const root = `export const RootSchema = J.object({\n${Object.keys(defs).map(n => `  ${JSON.stringify(n)}: ${n}Schema`).join(",\n")}\n}).unknown(false);`;
    return `// AUTO-GENERATED by schema-translator
import J from "joi";

${blocks.join("\n\n")}

${root}
`;
}
